<section class="page student-page"><div class="page-head"><div><span class="eyebrow">TEST SERIES</span><h1>Find your next mock test</h1><p>Browse by exam, category or subject.</p></div></div><form class="filters catalogue-filters"><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="Search by test name"><select name="exam"><option value="">All exams</option><?php foreach($exams as $exam):?><option value="<?=e($exam)?>" <?=($_GET['exam']??'')===$exam?'selected':''?>><?=e($exam)?></option><?php endforeach;?></select><select name="category"><option value="">All categories</option><?php foreach($categories as $category):?><option value="<?=e($category)?>" <?=($_GET['category']??'')===$category?'selected':''?>><?=e($category)?></option><?php endforeach;?></select><select name="subject"><option value="">All subjects</option><?php foreach($subjects as $s):?><option value="<?=e($s['id'])?>" <?=((int)($_GET['subject']??0)===(int)$s['id'])?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select><button class="btn">Search</button></form><div class="test-grid"><?php foreach($tests as $test)require __DIR__.'/test-card.php';?></div><?php if(!$tests):?><div class="empty card">No tests found. Try another exam, category, subject or keyword.</div><?php endif;?></section>
